 async function uploadDocument(){const f=document.getElementById('provider-document-file').files?.[0],type=document.getElementById('provider-document-type').value;if(!f)return show('Choose a document first.');if(f.size>4*1024*1024)return show('Each document must be 4 MB or smaller.');const btn=document.getElementById('provider-document-upload');btn.disabled=true;try{const r=await fetch(`/.netlify/functions/provider-document-upload?document_type=${encodeURIComponent(type)}&filename=${encodeURIComponent(f.name)}`,{method:'POST',credentials:'same-origin',headers:{'content-type':f.type||'application/octet-stream'},body:f}),d=await r.json().catch(()=>({}));if(r.status===401){location.replace('provider-login.html');return;}if(!r.ok)throw new Error(d.error||'Upload failed.');document.getElementById('provider-document-file').value='';show('Document uploaded and sent for Developer review.','success');await load({silent:true});}catch(e){show(e.message);}finally{btn.disabled=false;}}
