 async function removeDocument(id){if(!confirm('Remove this document from your active Provider record?'))return;try{await api('/.netlify/functions/provider-document-action',{method:'POST',body:JSON.stringify({document_id:id,action:'REMOVE'})});show('Document removed from your active record.','success');await load({silent:true});}catch(e){show(e.message);}} function providerRateLabel(r){const method=String(r.provider_compensation_method||((r.provider_compensation==null)?'NONE':'FIXED_CAD')).toUpperCase(),raw=r.provider_compensation==null?null:Number(r.provider_compensation),unit=String(r.billing_unit||'service').replace('_',' ');if(method==='FIXED_CAD'&&Number.isFinite(raw))return{method,main:money(raw),sub:`per ${unit}`};if(method==='PERCENT'&&Number.isFinite(raw))return{method,main:`${raw.toFixed(2).replace(/\.00$/,'')}%`,sub:'of PLEASE customer price'};return{method:'NONE',main:'Not set',sub:'Provider charge required'};}
 function updateRateCompUI(){const method=document.getElementById('provider-rate-comp-method')?.value||'FIXED_CAD',input=document.getElementById('provider-rate-comp'),label=document.getElementById('provider-rate-comp-label'),prefix=document.getElementById('provider-rate-comp-prefix'),suffix=document.getElementById('provider-rate-comp-suffix');if(!input)return;if(method==='PERCENT'){label.textContent='Provider Percentage';prefix.hidden=true;suffix.hidden=false;input.max='100';input.placeholder='70';}else{label.textContent='Provider Charge (CAD)';prefix.hidden=false;suffix.hidden=true;input.removeAttribute('max');input.placeholder='0.00';}updateRateSummary();}
 function updateRateSummary(){const name=document.getElementById('provider-rate-name')?.value.trim()||'New rate',unit=String(document.getElementById('provider-rate-unit')?.value||'hour').replace('_',' '),method=document.getElementById('provider-rate-comp-method')?.value||'FIXED_CAD',raw=Number(document.getElementById('provider-rate-comp')?.value);const summary=document.getElementById('provider-rate-summary-name'),unitEl=document.getElementById('provider-rate-summary-unit'),provider=document.getElementById('provider-rate-summary-provider'),methodEl=document.getElementById('provider-rate-summary-method');if(summary)summary.textContent=name;if(unitEl)unitEl.textContent=`per ${unit}`;if(provider){if(!Number.isFinite(raw)||raw<0){provider.textContent='Not set';methodEl.textContent='Enter your provider charge';}else if(method==='PERCENT'){provider.textContent=`${raw.toFixed(2).replace(/\.00$/,'')}%`;methodEl.textContent='of PLEASE customer price';}else{provider.textContent=money(raw);methodEl.textContent=`per ${unit}`;}}}
 function renderRates(){const sel=document.getElementById('provider-rate-service');if(sel){const cur=sel.value;sel.innerHTML='<option value="">Select service</option>'+(data.services||[]).map(s=>`<option value="${s.id}">${esc(s.name)}</option>`).join('');if([...sel.options].some(o=>o.value===cur))sel.value=cur;}const list=document.getElementById('provider-rate-list');if(!list)return;const sm=new Map((data.services||[]).map(s=>[s.id,s.name]));const rates=data.rates||[];list.innerHTML=rates.length?rates.map(r=>{const d=providerRateLabel(r),unit=String(r.billing_unit||'service').replace('_',' ');return `<article class="provider-rate-card ${r.active?'':'inactive'}"><div class="provider-rate-card-main"><div class="provider-rate-card-title"><div><span class="provider-rate-service-label">${esc(sm.get(r.service_id)||'Service')} · ${esc(unit)}</span><strong>${esc(r.rate_name)}</strong></div>${r.active?'<span class="provider-rate-active-pill">ACTIVE</span>':'<span class="provider-rate-inactive-pill">INACTIVE</span>'}</div><div class="provider-rate-card-metrics provider-rate-card-metrics-compact"><div><span>Your charge to PLEASE</span><strong>${esc(d.main)}</strong><small>${esc(d.sub)}</small></div><div><span>Customer selling price</span><strong>Set by PLEASE</strong><small>Separate from your provider rate</small></div></div>${r.description?`<p>${esc(r.description)}</p>`:''}</div><div class="provider-rate-card-actions">${r.active?`<button class="admin-outline-button provider-rate-edit" data-id="${r.id}">EDIT</button><button class="admin-danger-button provider-rate-deactivate" data-id="${r.id}">DEACTIVATE</button>`:''}</div></article>`}).join(''):'<p class="admin-muted">No service rates yet. Add the first provider rate above.</p>';document.querySelectorAll('.provider-rate-edit').forEach(b=>b.onclick=()=>editRate(b.dataset.id));document.querySelectorAll('.provider-rate-deactivate').forEach(b=>b.onclick=()=>deactivateRate(b.dataset.id));updateRateSummary();}
 function clearRateForm(){['provider-rate-id','provider-rate-name','provider-rate-description','provider-rate-comp'].forEach(id=>{const e=document.getElementById(id);if(e)e.value='';});const u=document.getElementById('provider-rate-unit');if(u)u.value='hour';const s=document.getElementById('provider-rate-service');if(s)s.value='';const m=document.getElementById('provider-rate-comp-method');if(m)m.value='FIXED_CAD';updateRateCompUI();}
 function editRate(id){const r=(data.rates||[]).find(x=>x.id===id);if(!r)return;document.getElementById('provider-rate-id').value=r.id;document.getElementById('provider-rate-service').value=r.service_id;document.getElementById('provider-rate-name').value=r.rate_name||'';document.getElementById('provider-rate-description').value=r.description||'';document.getElementById('provider-rate-unit').value=r.billing_unit||'service';document.getElementById('provider-rate-comp-method').value=r.provider_compensation_method&&r.provider_compensation_method!=='NONE'?r.provider_compensation_method:'FIXED_CAD';document.getElementById('provider-rate-comp').value=r.provider_compensation??'';updateRateCompUI();document.getElementById('provider-rate-name').focus();document.querySelector('.provider-rate-editor')?.scrollIntoView({behavior:'smooth',block:'start'});}
 async function saveRate(){const payload={id:document.getElementById('provider-rate-id').value,service_id:document.getElementById('provider-rate-service').value,rate_name:document.getElementById('provider-rate-name').value,description:document.getElementById('provider-rate-description').value,billing_unit:document.getElementById('provider-rate-unit').value,provider_compensation_method:document.getElementById('provider-rate-comp-method').value,provider_compensation:document.getElementById('provider-rate-comp').value};try{await api('/.netlify/functions/provider-service-rate-action',{method:'POST',body:JSON.stringify({action:'SAVE',payload})});clearRateForm();show('Provider rate saved. PLEASE can now use it to calculate your compensation on future Jobs.','success');await load({silent:true});}catch(e){show(e.message);}}
