 function render(){document.getElementById('provider-name').textContent=data.user.display_name;document.getElementById('provider-email').textContent=data.user.email;document.getElementById('provider-welcome').textContent=`Welcome, ${data.provider.display_name}`;const photo=safeUrl(data.provider?.profile_image_signed_url||data.provider?.profile_image_url);const storedName=document.getElementById('provider-profile-photo-file-name');if(storedName)storedName.textContent=data.provider?.profile_image_name?`Current file: ${data.provider.profile_image_name}`:(data.provider?.profile_image_path?'Current profile photo is stored.':'No profile photo uploaded yet.');['provider-header-photo','provider-overview-photo','provider-profile-photo-preview-img'].forEach(id=>{const img=document.getElementById(id);if(img){if(photo){img.onerror=()=>{img.removeAttribute('src');img.hidden=true;};img.src=photo;img.hidden=false;}else{img.removeAttribute('src');img.hidden=true;}}});const preview=document.getElementById('provider-profile-photo-preview');if(preview)preview.hidden=!photo;stats();renderOverview();renderAssignments();renderCalendar();renderManageServices();renderHistory();weeklyUI();exceptionsUI();renderProfile();renderDocuments();renderServicePhotos();renderAccount();renderRates();}
 let lastPendingIds=new Set();async function load({silent=false}={}){snapshotResponseDrafts();const next=await api('/.netlify/functions/provider-dashboard'),pendingIds=new Set((next.assignments||[]).filter(x=>x.status==='PENDING').map(x=>x.id)),hasNew=[...pendingIds].some(id=>!lastPendingIds.has(id));for(const id of [...responseDrafts.keys()])if(!pendingIds.has(id))responseDrafts.delete(id);data=next;render();lastPendingIds=pendingIds;if(hasNew&&!silent)show('New PLEASE assignment received. The scheduled time is reserved for this assignment.','success');}
